package com.praffull.programs;

public class ArithmeticOperators {

	public static void main(String[] args) {
		// TODO Auto-generated method stub
		int x,y;
		x=13;
		y=9;
		System.out.println(x+y);
		System.out.println(x-y);
		System.out.println(x*y);
		System.out.println(x/y);
		//remainder of division
		System.out.println(x%y);

	}

}
